 <div class="overlay" id="overlay"><section class="card" id="card"><div class="eyebrow" id="eyebrow">حكاية عن الصمود • لعبة منصات قصيرة</div><h1 id="title">من الظل<span>إلى القمّة</span></h1><p id="description">في زقاقٍ ضيّق تعلّم سنيك أن يراقب بصمت. حملته الغربة إلى مدينة لا تعرف اسمه، وأسقطته الخيبات أكثر من مرة… لكن في داخله جمرة لم تنطفئ.</p><div class="actions"><button class="primary" id="start">ابدأ الرحلة <span>←</span></button><button class="secondary" id="sound">الصوت: يعمل</button></div><div class="hint" id="hint"><span class="key">←</span><span class="key">→</span> حركة &nbsp; <span class="key">Space</span> قفز &nbsp; اجمع الجمرات، وتجاوز الظلال.</div></section></div>
 <div class="touch" id="touch"><div class="touchgroup"><button data-key="left" aria-label="تحرك يساراً">←</button><button data-key="right" aria-label="تحرك يميناً">→</button></div><button class="jump" data-key="jump" aria-label="اقفز">↑</button></div><div class="toast" id="toast"></div><div class="credit">A STORY OF RESILIENCE</div>
 </main>
 <script>
+(()=>{
+const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d');
+const $=id=>document.getElementById(id), overlay=$('overlay'),card=$('card'),hud=$('hud');
+let W=0,H=0,dpr=1,state='menu',last=0,camera=0,toastTimer=0,soundOn=true,audio;
+const worldEnd=3900, gravity=1700, speed=245;
+const chapters=[
+ {at:0,name:'البداية',title:'البذرة الأولى',text:'في الأزقة تعلّم أن يقرأ العيون قبل الكلام.'},
+ {at:900,name:'الغربة',title:'الطريق المجهول',text:'مدينةٌ جديدة، ليل بارد… ولا أحد يعرف اسمه.'},
+ {at:1900,name:'الانكسار',title:'من قلب الرماد',text:'ظنّوا أن الحكاية انتهت. لم يعرفوا أنه ينهض.'},
+ {at:2850,name:'العودة',title:'النار التي لا تنطفئ',text:'كل خطوةٍ موجعة صنعت طريقاً إلى القمّة.'}
+];
+const pits=[[680,770],[1440,1530],[2260,2350],[3160,3250]];
+const blocks=[{x:390,w:45,h:48},{x:1040,w:54,h:62},{x:1260,w:42,h:45},{x:1780,w:62,h:55},{x:2080,w:48,h:69},{x:2625,w:50,h:48},{x:2890,w:62,h:64},{x:3500,w:48,h:53}];
+const emberXs=[260,575,830,1110,1370,1660,1980,2185,2480,2770,3020,3400,3690];
+let embers=emberXs.map((x,i)=>({x,y:i%3===0?0:1,got:false,phase:i*1.7}));
+let player={x:90,y:0,vy:0,w:30,h:48,ground:true}; let checkpoint=90,found=0,held={left:false,right:false},jumpQueued=false;
+const arNum=n=>String(n).replace(/[0-9]/g,d=>'٠١٢٣٤٥٦٧٨٩'[d]);
+function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}
+new ResizeObserver(resize).observe(canvas); resize();
+function floorY(){return H-(innerWidth<700?94:104)}
+function chapterAt(x){let c=chapters[0];for(const v of chapters)if(x>=v.at)c=v;return c}
+function showToast(t){const e=$('toast');e.textContent=t;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),1500)}
+function playTone(freq=540){if(!soundOn)return;try{audio??=new AudioContext();let o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.055,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.17);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.18)}catch{}}
+function setStory(force=false){const c=chapterAt(player.x);$('chapter').textContent=c.name;$('storyTitle').textContent=c.title;$('storyText').textContent=c.text;$('progress').style.width=Math.min(100,player.x/worldEnd*100)+'%';$('embers').textContent='✦ '+arNum(found);if(force||c!==currentChapter){$('story').classList.add('show');currentChapter=c;setTimeout(()=>$('story').classList.remove('show'),3000)}}
+let currentChapter=null;
+function begin(){state='play';overlay.classList.add('hidden');hud.classList.add('visible');player={x:90,y:floorY()-48,vy:0,w:30,h:48,ground:true};camera=0;found=0;checkpoint=90;embers.forEach(e=>e.got=false);held={left:false,right:false};jumpQueued=false;currentChapter=null;setStory(true);last=performance.now()}
+function pause(){if(state==='play'){state='paused';showPanel('وقفة قصيرة','خذ نفساً… الرحلة بعدها مستمرة.','تابع الرحلة','استئناف');}else if(state==='paused'){state='play';overlay.classList.add('hidden');last=performance.now()}}
+function showPanel(kind,desc,btn,eyebrow){overlay.classList.remove('hidden');$('eyebrow').textContent=eyebrow;$('title').innerHTML=kind;$('description').textContent=desc;$('start').innerHTML=btn+' <span>←</span>';$('hint').textContent='اضغط Escape للإيقاف أو للعودة';$('sound').style.display='none'}
+function restartPanel(){state='menu';hud.classList.remove('visible');$('sound').style.display='';$('eyebrow').textContent='حكاية عن الصمود • لعبة منصات قصيرة';$('title').innerHTML='من الظل<span>إلى القمّة</span>';$('description').textContent='في زقاقٍ ضيّق تعلّم سنيك أن يراقب بصمت. حملته الغربة إلى مدينة لا تعرف اسمه، وأسقطته الخيبات أكثر من مرة… لكن في داخله جمرة لم تنطفئ.';$('start').innerHTML='ابدأ الرحلة <span>←</span>';$('hint').innerHTML='<span class="key">←</span><span class="key">→</span> حركة &nbsp; <span class="key">Space</span> قفز &nbsp; اجمع الجمرات، وتجاوز الظلال.';overlay.classList.remove('hidden')}
+$('start').addEventListener('click',()=>{if(state==='paused'){state='play';overlay.classList.add('hidden');last=performance.now()}else begin()});
+$('pause').addEventListener('click',pause);
+$('sound').addEventListener('click',()=>{$('sound').textContent=soundOn?'الصوت: مكتوم':'الصوت: يعمل';soundOn=!soundOn});
+window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','Space'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Escape'){pause();return}if(e.code==='ArrowLeft'||e.code==='KeyA')held.left=true;if(e.code==='ArrowRight'||e.code==='KeyD')held.right=true;if(['Space','ArrowUp','KeyW'].includes(e.code))jumpQueued=true});
+window.addEventListener('keyup',e=>{if(e.code==='ArrowLeft'||e.code==='KeyA')held.left=false;if(e.code==='ArrowRight'||e.code==='KeyD')held.right=false});
+document.querySelectorAll('.touch button').forEach(b=>{const key=b.dataset.key;const down=e=>{e.preventDefault();if(key==='jump')jumpQueued=true;else held[key]=true};const up=e=>{e.preventDefault();if(key!=='jump')held[key]=false};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up)});
+function inPit(x){return pits.find(p=>x+player.w>p[0]&&x<p[1])}
+function fail(){player.x=checkpoint;player.y=floorY()-player.h;player.vy=0;player.ground=true;camera=Math.max(0,player.x-W*.32);showToast('تعثر… لكنه ينهض من جديد');playTone(180)}
+function update(dt){if(state!=='play')return;dt=Math.min(dt,.033);let dir=(held.right?1:0)-(held.left?1:0);player.x=Math.max(0,Math.min(worldEnd-20,player.x+dir*speed*dt));let fy=floorY();if(jumpQueued&&player.ground){player.vy=-650;player.ground=false;playTone(310)}jumpQueued=false;player.vy+=gravity*dt;player.y+=player.vy*dt;
+let foot=player.y+player.h;const pit=inPit(player.x);if(!pit&&foot>=fy){player.y=fy-player.h;player.vy=0;player.ground=true}else player.ground=false;
+for(const b of blocks){if(player.x+player.w>b.x&&player.x<b.x+b.w&&player.y+player.h>fy-b.h){if(player.x+player.w/2<b.x+b.w/2){player.x=b.x-player.w;player.vy=0}else player.x=b.x+b.w}}
+if(player.y>H+70){fail()}
+for(const e of embers){if(e.got)continue;let ey=fy-(e.y===0?72:118)+Math.sin(performance.now()/400+e.phase)*5;if(Math.abs(player.x+player.w/2-e.x)<27&&Math.abs(player.y+player.h/2-ey)<36){e.got=true;found++;playTone(650+found*20);showToast('جمرة جديدة… لا تطفئها')}}
+if(player.x>checkpoint+500&&player.x<worldEnd-90){checkpoint=Math.floor(player.x/500)*500;}
+camera+=(Math.max(0,player.x-W*.33)-camera)*Math.min(1,dt*5);setStory();if(player.x>=worldEnd-45){state='won';hud.classList.remove('visible');showPanel('وصلَ إلى القمّة<span>والحكاية مستمرة</span>','لم يكن الطريق سهلاً. لكن كل سقوطٍ علّمه كيف يقف، وكل جمرةٍ جمعها ذكّرته أن النور يبدأ من الداخل. جمعتَ '+arNum(found)+' من ١٣ جمرة.','عِش الرحلة من جديد','النهاية • سنيك لم ينكسر');$('hint').textContent='إعادة اللعب تعيدك إلى بداية الحكاية';playTone(780)}}

