if(player.x>=worldEnd-45){state='won';hud.classList.remove('visible');showPanel('وصلَ إلى القمّة<span>والحكاية مستمرة</span>','لم يكن الطريق سهلاً. لكن كل سقوطٍ علّمه كيف يقف، وكل جمرةٍ جمعها ذكّرته أن النور يبدأ من الداخل. جمعتَ '+arNum(found)+' من ١٣ جمرة.','عِش الرحلة من جديد','النهاية • سنيك لم ينكسر');$('hint').textContent='إعادة اللعب تعيدك إلى بداية الحكاية';playTone(780)}}
function rng(n){let v=Math.sin(n*127.1+311.7)*43758.5453;return v-Math.floor(v)}
function drawBackground(t){let fy=floorY(),zone=chapterAt(Math.max(0,camera+W*.45)),idx=chapters.indexOf(zone);let colors=[['#22242b','#4a3837','#aa674c'],['#131b27','#35475a','#bd8057'],['#17151b','#38282f','#a35743'],['#19242a','#516454','#dfad67']][idx];let g=ctx.createLinearGradient(0,0,0,fy);g.addColorStop(0,colors[0]);g.addColorStop(.64,colors[1]);g.addColorStop(1,colors[2]);ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
// distant glow
let glow=ctx.createRadialGradient(W*.76,H*.35,4,W*.76,H*.35,W*.48);glow.addColorStop(0,idx===3?'#edb65f35':'#d18a6530');glow.addColorStop(1,'#11131a00');ctx.fillStyle=glow;ctx.fillRect(0,0,W,fy);
// stars and moon
for(let i=0;i<55;i++){let x=((i*173-camera*.08)%(W+80)+W+80)%(W+80)-40,y=25+rng(i)*fy*.48;ctx.globalAlpha=.22+rng(i+77)*.42;ctx.fillStyle='#ffe9c5';ctx.beginPath();ctx.arc(x,y,rng(i+3)*1.3+.35,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
let mx=W*.79,my=H*.24;ctx.fillStyle='#f0cb8a';ctx.globalAlpha=.68;ctx.beginPath();ctx.arc(mx,my,22,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle=colors[0];ctx.beginPath();ctx.arc(mx+10,my-8,20,0,Math.PI*2);ctx.fill();
// distant terrain/buildings move slowly
ctx.fillStyle=idx===1?'#18212c':'#26262b';ctx.beginPath();ctx.moveTo(0,fy-12);for(let x=0;x<=W+20;x+=12){let wx=x+camera*.18;let h=idx===1?52+rng(Math.floor(wx/37))*110:36+rng(Math.floor(wx/42))*75;ctx.lineTo(x,fy-h)}ctx.lineTo(W,fy);ctx.lineTo(0,fy);ctx.fill();
ctx.fillStyle=idx===3?'#293b38':'#171a20';ctx.beginPath();ctx.moveTo(0,fy);for(let x=0;x<=W+30;x+=20){let wx=x+camera*.38;let h=48+rng(Math.floor(wx/26)+20)*95;ctx.lineTo(x,fy-h)}ctx.lineTo(W,fy+5);ctx.lineTo(0,fy+5);ctx.fill();
// warm horizon seam
let hg=ctx.createLinearGradient(0,fy-100,0,fy+15);hg.addColorStop(0,'#0000');hg.addColorStop(1,'#e1a15b18');ctx.fillStyle=hg;ctx.fillRect(0,fy-100,W,110);
}
function drawWorld(t){let fy=floorY();ctx.save();ctx.translate(-camera,0);
// ground sections and pits
ctx.fillStyle='#17171b';let start=Math.max(0,camera-40),end=camera+W+60,cur=start;for(const p of pits){if(p[1]<start||p[0]>end)continue;if(p[0]>cur)ctx.fillRect(cur,fy,p[0]-cur,H-fy+20);cur=p[1]}ctx.fillRect(cur,fy,Math.max(0,end-cur),H-fy+20);
// ground top rim
ctx.fillStyle='#b17754';for(const p of pits){ctx.fillRect(Math.max(start,p[1]),fy,Math.max(0,end-Math.max(start,p[1])),2)}
// ground little grit
for(let i=Math.floor(start/48);i<Math.ceil(end/48);i++){let x=i*48+13*rng(i);if(inAnyPit(x))continue;ctx.fillStyle='#d3a17440';ctx.fillRect(x,fy+16+rng(i+9)*29,2,2);ctx.fillStyle='#bd87634a';ctx.fillRect(x+12,fy+48+rng(i+4)*17,5,1)}
// stage silhouettes and chapter markers
for(let s=1;s<4;s++){let x=chapters[s].at;if(x>start-300&&x<end+300){ctx.strokeStyle='#edb65f35';ctx.setLineDash([3,8]);ctx.beginPath();ctx.moveTo(x,fy-145);ctx.lineTo(x,fy-15);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#edb65f77';ctx.font='11px Changa';ctx.textAlign='center';ctx.fillText(['','الغربة','الانكسار','العودة'][s],x,fy-155)}}
// blocks as dark fractured obstacles
for(const b of blocks){let x=b.x;if(x<start-100||x>end+100)continue;ctx.fillStyle='#0d1014';ctx.beginPath();ctx.moveTo(x,fy);ctx.lineTo(x+4,fy-b.h+8);ctx.lineTo(x+b.w*.42,fy-b.h);ctx.lineTo(x+b.w*.53,fy-b.h+10);ctx.lineTo(x+b.w,fy-b.h+4);ctx.lineTo(x+b.w,fy);ctx.fill();ctx.strokeStyle='#bd7654';ctx.globalAlpha=.55;ctx.beginPath();ctx.moveTo(x+5,fy-2);ctx.lineTo(x+b.w*.42,fy-b.h+4);ctx.lineTo(x+b.w*.62,fy-b.h*.44);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle='#efb166';ctx.globalAlpha=.5;ctx.fillRect(x+8,fy-b.h+11,4,2);ctx.globalAlpha=1}
// collectibles
for(const e of embers){if(e.got||e.x<start-40||e.x>end+40)continue;let y=fy-(e.y===0?72:118)+Math.sin(t/400+e.phase)*5;ctx.save();ctx.shadowBlur=22;ctx.shadowColor='#ffbd61';ctx.fillStyle='#ffd786';ctx.beginPath();ctx.arc(e.x,y,4.2,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#ffd78655';ctx.beginPath();ctx.arc(e.x,y,9+Math.sin(t/250+e.phase)*2,0,Math.PI*2);ctx.stroke();ctx.restore()}
// finish beacon
if(worldEnd>start-100&&worldEnd<end+200){ctx.fillStyle='#f1c276';ctx.globalAlpha=.8;ctx.fillRect(worldEnd,fy-180,2,180);ctx.beginPath();ctx.moveTo(worldEnd+2,fy-180);ctx.lineTo(worldEnd+55,fy-164);ctx.lineTo(worldEnd+2,fy-147);ctx.fill();ctx.globalAlpha=1;ctx.shadowBlur=25;ctx.shadowColor='#f3bb64';ctx.fillStyle='#f4c578';ctx.beginPath();ctx.arc(worldEnd+1,fy-190,5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}
// player silhouette, scarf trailing
let px=player.x,py=player.y;ctx.save();if(state==='menu'||state==='paused'||state==='won'){}ctx.translate(px+player.w/2,py+player.h/2);let bob=player.ground?Math.sin(t/110)*1.2:0;
// scarf
ctx.fillStyle='#bd6247';ctx.beginPath();ctx.moveTo(-5,-10);ctx.quadraticCurveTo(-22,-7,-31,-2+Math.sin(t/100)*3);ctx.lineTo(-19,3);ctx.lineTo(-5,0);ctx.fill();
// body cloak
ctx.fillStyle='#11151a';ctx.beginPath();ctx.moveTo(-11,-7);ctx.quadraticCurveTo(-13,10,-10,21);ctx.lineTo(10,21);ctx.quadraticCurveTo(13,5,10,-8);ctx.closePath();ctx.fill();ctx.fillStyle='#2e3031';ctx.beginPath();ctx.moveTo(-10,16);ctx.lineTo(-13,24);ctx.lineTo(-2,24);ctx.lineTo(0,18);ctx.lineTo(3,24);ctx.lineTo(13,24);ctx.lineTo(10,15);ctx.fill();
// hood/head
ctx.fillStyle='#171a1f';ctx.beginPath();ctx.arc(0,-12+bob,12,Math.PI,0);ctx.lineTo(11,-4);ctx.lineTo(-11,-4);ctx.closePath();ctx.fill();ctx.fillStyle='#dca967';ctx.fillRect(3,-11+bob,5,2);ctx.fillStyle='#f4c271';ctx.fillRect(5,-11+bob,2,2);
// chest glimmer
ctx.fillStyle='#d79450';ctx.globalAlpha=.72;ctx.fillRect(-2,1,2,8);ctx.globalAlpha=1;ctx.restore();ctx.restore();
// wind streaks in travel chapters
if(player.x>900&&player.x<worldEnd){ctx.globalAlpha=.13;ctx.strokeStyle='#e7d4b8';for(let i=0;i<5;i++){let x=(i*173+t*.07)%W,y=H*.28+i*31;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+25+12*rng(i),y);ctx.stroke()}ctx.globalAlpha=1}
}
function inAnyPit(x){return pits.some(p=>x>=p[0]&&x<=p[1])}
function draw(t){ctx.clearRect(0,0,W,H);drawBackground(t);drawWorld(t);if(state==='menu'){let fy=floorY();ctx.fillStyle='#edb65f12';ctx.fillRect(0,fy,W,1)}}
function frame(t){update((t-last)/1000||0);last=t;draw(t);requestAnimationFrame(frame)}requestAnimationFrame(frame);
})();
</script>
</body>
</html>

